#pragma once#include "BaseReader.h"class KUPDN : public KBaseReader{public:  KUPDN();  virtual std::string GetType() const  {    return "UPDN";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_settings;};//////////////////////////////////////////////////////////////////////////class KUPDNFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KUPDN();    return ptr;  }};